// The SIGIL interface, compiled in.
//
// A plugin that needs the internet is not a plugin, so the static export of the
// Next app is embedded byte-for-byte rather than fetched or read from a path
// beside the bundle. ui-bundle.cpp is GENERATED by scripts/build-plugin-ui.mjs
// and is not checked in - run `pnpm run build:plugin-ui` before configuring the
// plugin target, which is also what the CMake dependency on it enforces.
#pragma once

#include <cstddef>

namespace sigil::ui {

struct Asset {
  /** Root-relative, with the leading slash: "/index.html", "/_next/…". */
  const char* path;
  /** Content-Type, decided at generation time from the extension. */
  const char* mime;
  const unsigned char* data;
  std::size_t size;
};

extern const Asset kAssets[];
extern const int kAssetCount;

/**
 * Looks a request up. `path` is what the WebView asked for, so "/" is normalised
 * to "/index.html" and a query string is ignored. Returns nullptr when there is
 * no such asset, which the resource provider turns into a failed request rather
 * than an empty 200 - a silent empty file looks like a broken UI with no clue
 * why.
 */
const Asset* findAsset(const char* path);

}  // namespace sigil::ui
